import type { Dispatch } from 'react';
import React from 'react';
import { FormattedMessage } from 'react-intl';

import { formatDate } from '@dynatrace-sdk/units';
import { getRegionalFormat } from '@dynatrace-sdk/user-preferences';

import type { TimeValue, TimeframeV2 } from '../../../../core/types/time.js';
import { uuidv4 } from '../../../../core/utils/uuidv4.js';
import {
  FormFieldMessagesAction,
  type FormFieldMessagesReducerAction,
} from '../../../forms-core/state/formfield-messages-state-reducer.js';
import { _isTimeframeV2 } from '../../../forms-core/time/types.js';
import type { _CalendarState } from '../types/shared-types.js';
import { _isOutOfBounds } from '../utils/helpers.js';

/**
 * @param term - word used to describe the selection. Date for single selection and timeframe for a range.
 * @internal
 */
function getOutOfBoundsError(term: string, min?: Date, max?: Date) {
  if (min && max) {
    return (
      <FormattedMessage
        id="LNWPcycjuDPimFKd"
        defaultMessage="Please select a {term} within the range of {min} and {max}."
        description="Error message for a date or a timeframe outside the selectable range."
        values={{
          min: formatDate(min, {
            locale: getRegionalFormat(),
          }),
          max: formatDate(max, {
            locale: getRegionalFormat(),
          }),
          term,
        }}
      />
    );
  }

  if (min) {
    return (
      <FormattedMessage
        id="9XjoWQoeIKxStpgZ"
        defaultMessage="Please select a {term} later than {min}."
        description="Error message for a date or a timeframe earlier than the required minimum."
        values={{ min: min.toLocaleDateString(), term }}
      />
    );
  }

  if (max) {
    return (
      <FormattedMessage
        id="0Y8wN2jk+BAa2NoC"
        defaultMessage="Please select a {term} earlier than {max}."
        description="Error message for a date or a timeframe later then the expected maximum."
        values={{ max: max.toLocaleDateString(), term }}
      />
    );
  }
}

/** @internal */
export function _validateCalendarSelection(
  updatedValue: Partial<TimeframeV2> | TimeValue | null,
  state: _CalendarState,
  formMessageDispatch: Dispatch<FormFieldMessagesReducerAction>,
) {
  if (!_isTimeframeV2(updatedValue, state.type)) {
    if (_isOutOfBounds(updatedValue?.absoluteDate, state.min, state.max)) {
      // Prevents overwriting of already existing errors
      if (state.errorId) {
        return state.errorId;
      }

      const id = `strato-${uuidv4()}`;
      formMessageDispatch({
        type: FormFieldMessagesAction.ADDMESSAGE,
        payload: {
          id,
          variant: 'error',
          messageType: 'formcontrol',
          message: getOutOfBoundsError('date', state.min, state.max),
          validityStateKey: 'customError',
        },
      });
      return id;
    }
  }

  if (_isTimeframeV2(updatedValue, state.type)) {
    if (
      _isOutOfBounds(updatedValue?.from?.absoluteDate, state.min, state.max) ||
      _isOutOfBounds(updatedValue?.to?.absoluteDate, state.min, state.max)
    ) {
      // Prevents overwriting of already existing errors
      if (state.errorId) {
        return state.errorId;
      }

      const id = `strato-${uuidv4()}`;
      formMessageDispatch({
        type: FormFieldMessagesAction.ADDMESSAGE,
        payload: {
          id,
          variant: 'error',
          messageType: 'formcontrol',
          message: getOutOfBoundsError('timeframe', state.min, state.max),
          validityStateKey: 'customError',
        },
      });

      return id;
    }
  }

  // Clean up old errors
  if (state.errorId) {
    formMessageDispatch({
      type: FormFieldMessagesAction.REMOVEMESSAGE,
      payload: {
        id: state.errorId,
        messageType: 'formcontrol',
      },
    });
  }
}
